43	.btn{border:1px solid var(--blue);background:var(--blue);color:#fff;border-radius:.35rem;padding:.45rem 1.1rem;text-decoration:none;display:inline-block}
44	.btn.secondary{background:#fff;color:var(--blue)}
45	.link{border:none;background:none;color:var(--blue);padding:0;font-size:.92rem}
46	.link.danger{color:var(--red)}
