468	
469	def validate_survey(obj):
470	    """Validate a decoded survey payload.
471	
472	    Returns (clean_survey, None) on success or (None, error_message) on failure.
473	    Strings are stored trimmed of surrounding whitespace; description keeps its
474	    raw value so Chinese, quotes and newlines are preserved.
475	    """
476	    if not isinstance(obj, dict):
477	        return None, "请求体必须是 JSON 对象"
478	    if "title" not in obj:
479	        return None, "缺少字段 title"
480	    title = obj["title"]
481	    if not isinstance(title, str):
482	        return None, "title 必须是字符串"
483	    title = title.strip()
484	    if not title:
485	        return None, "title 不能为空（或全为空白字符）"
486	
487	    description = obj.get("description", "")
488	    if not isinstance(description, str):
489	        return None, "description 必须是字符串"
490	
491	    if "questions" not in obj:
492	        return None, "缺少字段 questions"
493	    raw_questions = obj["questions"]
494	    if not isinstance(raw_questions, list):
495	        return None, "questions 必须是数组"
496	    if len(raw_questions) == 0:
497	        return None, "questions 至少需要一道题"
498	
499	    questions = []
500	    for index, raw_question in enumerate(raw_questions, start=1):
501	        location = f"第 {index} 题"
502	        if not isinstance(raw_question, dict):
503	            return None, f"{location}（questions[{index - 1}]）必须是对象"
504	
505	        if "type" not in raw_question:
506	            return None, f"{location}：缺少字段 type"
507	        question_type = raw_question["type"]
508	        if not isinstance(question_type, str):
509	            return None, f"{location}：type 必须是字符串"
510	        if question_type not in QUESTION_TYPES:
511	            shown = json.dumps(question_type, ensure_ascii=False)
512	            return None, f"{location}：不支持的题型 {shown}（仅支持 text 或 single_choice）"
513	
514	        if "title" not in raw_question:
515	            return None, f"{location}：缺少字段 title"
516	        question_title = raw_question["title"]
517	        if not isinstance(question_title, str):
518	            return None, f"{location}：title 必须是字符串"
519	        question_title = question_title.strip()
520	        if not question_title:
521	            return None, f"{location}：题目标题不能为空（或全为空白字符）"
522	
523	        required = raw_question.get("required", False)
524	        if not isinstance(required, bool):
525	            return None, f"{location}：required 必须是布尔值"
526	
527	        raw_options = raw_question.get("options", [])
528	        if not isinstance(raw_options, list):
529	            return None, f"{location}：options 必须是数组"
530	
531	        options = []
532	        if question_type == "text":
533	            if len(raw_options) > 0:
534	                return None, f"{location}：文本题不能包含选项（options 必须省略或为空数组）"
535	        else:
536	            if len(raw_options) < 2:
537	                return None, f"{location}：单选题至少需要两个选项"
538	            seen = set()
539	            for option_index, raw_option in enumerate(raw_options, start=1):
540	                if not isinstance(raw_option, str):
541	                    return None, f"{location}：第 {option_index} 个选项必须是字符串"
542	                option = raw_option.strip()
543	                if not option:
544	                    return None, f"{location}：第 {option_index} 个选项不能为空（或全为空白字符）"
545	                if option in seen:
546	                    shown = json.dumps(option, ensure_ascii=False)
547	                    return None, f"{location}：选项 {shown} 重复（同一题内选项不得重复）"
548	                seen.add(option)
549	                options.append(option)
550	
551	        questions.append({
552	            "type": question_type,
553	            "title": question_title,
554	            "required": required,
555	            "options": options,
556	        })
557	
558	    return {
559	        "title": title,
560	        "description": description,
561	        "questions": questions,
562	    }, None
563	
564	
565	def main():
566	    parser = argparse.ArgumentParser(description="OpenSurvey - 问卷调查与反馈管理")
567	    commands = parser.add_subparsers(dest="command", required=True)
568	    serve = commands.add_parser("serve", help="Start the HTTP service")
569	    serve.add_argument("--host", default="127.0.0.1", help="Address to bind (default: 127.0.0.1)")
570	    serve.add_argument("--port", type=int, default=8080, help="Port to bind; 0 selects an available port")
571	    serve.add_argument("--data-dir", type=Path, default=Path("data"), help="Directory for the local SQLite database")
572	    args = parser.parse_args()
573	    if not 0 <= args.port <= 65535:
574	        parser.error("port must be between 0 and 65535")
575	    args.data_dir.mkdir(parents=True, exist_ok=True)
576	    database = sqlite3.connect(args.data_dir / "open-survey.sqlite")
577	    database.execute("CREATE TABLE IF NOT EXISTS surveys (id INTEGER PRIMARY KEY, title TEXT NOT NULL)")
578	    columns = {row[1] for row in database.execute("PRAGMA table_info(surveys)")}
579	    if "description" not in columns:
580	        database.execute("ALTER TABLE surveys ADD COLUMN description TEXT NOT NULL DEFAULT ''")
581	    database.execute(
582	        "CREATE TABLE IF NOT EXISTS questions ("
583	        "id INTEGER PRIMARY KEY, survey_id INTEGER NOT NULL, position INTEGER NOT NULL, "
584	        "type TEXT NOT NULL, title TEXT NOT NULL, required INTEGER NOT NULL)"
585	    )
586	    database.execute(
587	        "CREATE TABLE IF NOT EXISTS question_options ("
588	        "id INTEGER PRIMARY KEY, question_id INTEGER NOT NULL, position INTEGER NOT NULL, text TEXT NOT NULL)"
589	    )
590	    database.commit()
591	
592	    def survey_detail(survey_id):
593	        row = database.execute(
594	            "SELECT title, COALESCE(description, '') FROM surveys WHERE id = ?",
595	            (survey_id,),
596	        ).fetchone()
597	        if row is None:
598	            return None
599	        title, description = row
600	        questions = []
601	        question_rows = database.execute(
602	            "SELECT id, type, title, required FROM questions WHERE survey_id = ? ORDER BY position",
603	            (survey_id,),
604	        ).fetchall()
605	        for question_id, question_type, question_title, required in question_rows:
606	            options = [option_row[0] for option_row in database.execute(
607	                "SELECT text FROM question_options WHERE question_id = ? ORDER BY position",
608	                (question_id,),
609	            )]
610	            questions.append({
611	                "type": question_type,
612	                "title": question_title,
613	                "required": bool(required),
614	                "options": options,
615	            })
616	        return {
617	            "id": survey_id,
618	            "title": title,
619	            "description": description,
620	            "questions": questions,
621	        }
622	
623	    def save_survey(clean):
624	        """Insert the whole survey atomically; returns the new id."""
625	        try:
626	            cursor = database.execute(
627	                "INSERT INTO surveys (title, description) VALUES (?, ?)",
628	                (clean["title"], clean["description"]),
629	            )
630	            survey_id = cursor.lastrowid
631	            write_questions(survey_id, clean["questions"])
632	            database.commit()
633	            return survey_id
634	        except Exception:
635	            database.rollback()
636	            raise
637	
638	    def write_questions(survey_id, questions):
639	        """Replace all questions/options of a survey with the given ordered list."""
640	        old_question_ids = [row[0] for row in database.execute(
641	            "SELECT id FROM questions WHERE survey_id = ?", (survey_id,)
642	        )]
643	        if old_question_ids:
644	            placeholders = ",".join("?" for _ in old_question_ids)
645	            database.execute(
646	                f"DELETE FROM question_options WHERE question_id IN ({placeholders})",
647	                old_question_ids,
648	            )
649	        database.execute("DELETE FROM questions WHERE survey_id = ?", (survey_id,))
650	        for position, question in enumerate(questions):
651	            question_cursor = database.execute(
652	                "INSERT INTO questions (survey_id, position, type, title, required) "
653	                "VALUES (?, ?, ?, ?, ?)",
654	                (survey_id, position, question["type"], question["title"],
655	                 1 if question["required"] else 0),
656	            )
657	            question_id = question_cursor.lastrowid
658	            for option_position, option in enumerate(question["options"]):
659	                database.execute(
660	                    "INSERT INTO question_options (question_id, position, text) VALUES (?, ?, ?)",
661	                    (question_id, option_position, option),
662	                )
663	
664	    def replace_survey(survey_id, clean):
665	        """Replace a whole survey atomically; keeps the same id.
666	
667	        Returns False when the survey does not exist (no record is created).
668	        """
669	        row = database.execute("SELECT 1 FROM surveys WHERE id = ?", (survey_id,)).fetchone()
670	        if row is None:
671	            return False
672	        try:
673	            database.execute(
674	                "UPDATE surveys SET title = ?, description = ? WHERE id = ?",
675	                (clean["title"], clean["description"], survey_id),
676	            )
677	            write_questions(survey_id, clean["questions"])
678	            database.commit()
679	            return True
680	        except Exception:
681	            database.rollback()
682	            raise
683	
684	    class Handler(BaseHTTPRequestHandler):
685	        def respond(self, status, value, *, html=False, allow=None):
686	            payload = value.encode("utf8") if html else json.dumps(value, ensure_ascii=False).encode("utf8")
687	            self.send_response(status)
688	            self.send_header("Content-Type", "text/html; charset=utf-8" if html else "application/json; charset=utf-8")
689	            self.send_header("Content-Length", str(len(payload)))
690	            if status == 405 and allow is not None:
691	                self.send_header("Allow", ", ".join(allow))
692	            self.end_headers()
693	            self.wfile.write(payload)
694	
695	        def list_surveys(self):
696	            records = [
697	                {"id": row[0], "title": row[1]}
698	                for row in database.execute("SELECT id, title FROM surveys ORDER BY id")
699	            ]
700	            self.respond(200, {RESOURCE: records})
701	
702	        def read_payload(self):
703	            """Read and decode a JSON request body.
704	
705	            Returns (payload, None) or (None, error_message).
706	            """
707	            try:
708	                length = int(self.headers.get("Content-Length") or 0)
709	            except ValueError:
710	                length = -1
711	            if length < 0:
712	                return None, "Content-Length 无效"
713	            if length > MAX_BODY_BYTES:
714	                return None, "请求体过大"
715	            body = self.rfile.read(length) if length else b""
716	            try:
717	                return json.loads(body.decode("utf8")), None
718	            except (UnicodeDecodeError, json.JSONDecodeError) as error:
719	                return None, f"请求体不是合法 JSON：{error}"
720	
721	        def create_survey(self):
722	            payload, error = self.read_payload()
723	            if error is not None:
724	                self.respond(400, {"error": error})
725	                return
726	
727	            clean, error = validate_survey(payload)
728	            if error is not None:
729	                self.respond(400, {"error": error})
730	                return
731	            try:
732	                survey_id = save_survey(clean)
733	            except sqlite3.DatabaseError as error:
734	                self.respond(500, {"error": f"保存失败：{error}"})
735	                return
736	            result = {"id": survey_id, **clean}
737	            self.respond(201, result)
738	
739	        def update_survey(self, survey_id):
740	            payload, read_error = self.read_payload()
741	            if survey_detail(survey_id) is None:
742	                # Editing a missing id is always 404 and must never create one.
743	                self.respond(404, {"error": "not found"})
744	                return
745	            if read_error is not None:
746	                self.respond(400, {"error": read_error})
747	                return
748	
749	            # Full replacement: validate before touching the stored draft so a
750	            # rejected request leaves the old survey exactly as it was.
751	            clean, error = validate_survey(payload)
752	            if error is not None:
753	                self.respond(400, {"error": error})
754	                return
755	            try:
756	                replace_survey(survey_id, clean)
757	            except sqlite3.DatabaseError as error:
758	                self.respond(500, {"error": f"保存失败：{error}"})
759	                return
760	            self.respond(200, {"id": survey_id, **clean})
761	
762	        def route(self):
763	            location = urlsplit(self.path).path
764	            detail_match = re.fullmatch(r"/api/surveys/(\d+)", location)
765	
766	            if location == "/api/surveys":
767	                allowed = ["GET", "POST"]
768	            elif location in ("/", "/health"):
769	                allowed = ["GET"]
770	            elif detail_match:
771	                allowed = ["GET", "PUT"]
772	            else:
773	                self.respond(404, {"error": "not found"})
774	                return
775	
776	            if self.command not in allowed:
777	                self.respond(405, {"error": "method not allowed"}, allow=allowed)
778	                return
779	
780	            if location == "/":
781	                self.respond(200, PAGE, html=True)
782	            elif location == "/health":
783	                self.respond(200, {"status": "ok", "product": PRODUCT})
784	            elif location == "/api/surveys":
785	                if self.command == "POST":
786	                    self.create_survey()
787	                else:
788	                    self.list_surveys()
789	            else:
790	                survey_id = int(detail_match.group(1))
791	                if self.command == "PUT":
792	                    self.update_survey(survey_id)
793	                    return
794	                detail = survey_detail(survey_id)
795	                if detail is None:
796	                    self.respond(404, {"error": "not found"})
797	                else:
798	                    self.respond(200, detail)
799	
800	        do_GET = do_POST = do_PUT = do_PATCH = do_DELETE = do_HEAD = do_OPTIONS = route
801	
802	    def stop(_signal, _frame):
803	        raise KeyboardInterrupt
804	
805	    signal.signal(signal.SIGTERM, stop)
806	    server = None
807	    try:
808	        server = HTTPServer((args.host, args.port), Handler)
809	        host, port = server.server_address[:2]
810	        address = f"[{host}]" if ":" in host else host
811	        print(f"{PRODUCT} listening on http://{address}:{port}", flush=True)
812	        server.serve_forever()
813	    except KeyboardInterrupt:
814	        pass
815	    finally:
816	        if server is not None:
817	            server.server_close()
818	        database.close()
819	
820	
821	if __name__ == "__main__":
822	    main()
